-- Sugandha Candles — catalogue content.
-- Generated from src/lib/seed.ts. Paste into Supabase → SQL Editor → Run.
-- Safe to run twice: it updates rows that already exist.

-- Only one collection for now, so clear out any leftovers from the first setup.
delete from public.products where collection_slug <> 'festive-candles';
delete from public.collections where slug <> 'festive-candles';

on conflict (slug) do update set
  name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  cover_image = excluded.cover_image, sort_order = excluded.sort_order;

on conflict (slug) do update set
  name = excluded.name, collection_slug = excluded.collection_slug, tagline = excluded.tagline, description = excluded.description, images = excluded.images, keywords = excluded.keywords, fragrance = excluded.fragrance, wax_type = excluded.wax_type, wick_type = excluded.wick_type, burn_time_hours = excluded.burn_time_hours, height_cm = excluded.height_cm, diameter_cm = excluded.diameter_cm, weight_grams = excluded.weight_grams, base_price = excluded.base_price, mrp = excluded.mrp, price_tiers = excluded.price_tiers, packaging = excluded.packaging, in_stock = excluded.in_stock, featured = excluded.featured, sort_order = excluded.sort_order;

on conflict (id) do update set data = excluded.data, updated_at = now();

