insert into public.collections (slug, name, tagline, description, cover_image, sort_order) values
  ('festive-candles', 'Festive Candles', 'Diwali, weddings, gifting', 'Brass urlis, lotus ponds, diya sets and gift boxes — the pieces that sell through the festive season and carry a brand well. All poured in 100% natural soy wax with imported fragrance.', '/products/peacock-urli-candle/peacock-urli-candle-1.jpg', 1)
insert into public.products (slug, name, collection_slug, tagline, description, images, keywords, fragrance, wax_type, wick_type, burn_time_hours, height_cm, diameter_cm, weight_grams, base_price, mrp, price_tiers, packaging, in_stock, featured, sort_order) values
('peacock-urli-candle', 'Peacock Urli Candle', 'festive-candles', 'Our best seller, and it shows', 'An ornate gold peacock urli with a deep teal centre pool, a hand-sculpted lotus floating in it, and small diya wells around the rim each holding a rose. It photographs beautifully on a Diwali table, which is exactly why it moves the way it does.', ARRAY['/products/peacock-urli-candle/peacock-urli-candle-1.jpg']::text[], ARRAY['peacock','urli','brass','gold','lotus','diya','diwali','rangoli','gifting','pooja']::text[], 'Jasmine, White Oud, French Vanilla', '100% natural soy wax', 'Cotton, lead-free', 22, 5.08, 19.05, 620, 699, 725, '[{"minQty":1,"price":699},{"minQty":10,"price":630},{"minQty":25,"price":575},{"minQty":50,"price":510},{"minQty":100,"price":455}]'::jsonb, 'Foam-nested in a printed carton', true, true, 1),
('lotus-pond-urli-candle', 'Lotus Pond Urli Candle', 'festive-candles', 'A whole pond, in wax', 'A scalloped brass urli filled with a still blue water pool, with hand-shaped lotus blooms and lily pads resting on the surface. The water effect is solid wax throughout, so nothing spills and nothing needs topping up.', ARRAY['/products/lotus-pond-urli-candle/lotus-pond-urli-candle-1.jpg']::text[], ARRAY['lotus','pond','urli','water','blue','brass','diwali','centrepiece','gifting','pooja']::text[], 'White Oud, Black Oud', '100% natural soy wax', 'Cotton, lead-free', 24, 3.81, 11.43, 700, 399, 425, '[{"minQty":1,"price":399},{"minQty":10,"price":360},{"minQty":25,"price":325},{"minQty":50,"price":290},{"minQty":100,"price":260}]'::jsonb, 'Foam-nested in a printed carton', true, true, 2),
('mithai-box-candle', 'Mithai Box Candle', 'festive-candles', 'Looks like a sweet box. Isn''t.', 'Motichoor-style laddoos and barfi finished with edible-looking silver leaf, set in a clear-lid gift box. Buyers hand these over as mithai and watch the face change when they realise. Our strongest corporate and return-gift piece.', ARRAY['/products/mithai-box-candle/mithai-box-candle-1.jpg']::text[], ARRAY['mithai','laddoo','barfi','sweet','dessert','gift box','corporate','return gift','diwali','novelty']::text[], 'Kesar Chandan, Pineapple', '100% natural soy wax', 'Cotton, lead-free', 10, 0, 0, 380, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, '6-piece cavity gift box', true, true, 3),
('lotus-pond-boat-candle', 'Lotus Pond Boat Candle', 'festive-candles', 'Long oval, lotuses and little boats', 'A long oval stone-finish tray holding a blue water pool with pink lotus blooms and two tiny wooden-look boats. It suits a long dining table or a console where a round urli would look lost.', ARRAY['/products/lotus-pond-boat-candle/lotus-pond-boat-candle-1.jpg']::text[], ARRAY['lotus','boat','pond','oval','water','blue','table','centrepiece','wedding','diwali']::text[], 'Lavender, Jasmine', '100% natural soy wax', 'Cotton, lead-free', 20, 6.35, 15.24, 560, 449, 475, '[{"minQty":1,"price":449},{"minQty":10,"price":405},{"minQty":25,"price":370},{"minQty":50,"price":330},{"minQty":100,"price":290}]'::jsonb, 'Foam-nested in a printed carton', true, false, 4),
('designer-lotus-candle', 'Designer Lotus Candle', 'festive-candles', 'Free-standing, sold as a pair', 'Hand-sculpted lotus blooms in graded pink with green leaf bases, sold as a matched pair. They float, or sit on a plate as they are. The most flexible piece we make for decorators.', ARRAY['/products/designer-lotus-candle/designer-lotus-candle-1.jpg']::text[], ARRAY['lotus','floating','pair','pink','decor','wedding','event','float','pooja','urli filler']::text[], 'Mogra', '100% natural soy wax', 'Cotton, lead-free', 6, 6.35, 8.89, 130, 129, 155, '[{"minQty":1,"price":129},{"minQty":10,"price":115},{"minQty":25,"price":105},{"minQty":50,"price":95},{"minQty":100,"price":85}]'::jsonb, 'Pair per box, 12 pairs per carton', true, false, 5),
('lotus-boat-tealight-box', 'Lotus Boat Tealight Box', 'festive-candles', 'Six pond cups in one box', 'Six individual cups, each a miniature blue pond with a lotus or a boat on the surface, in a clear-lid gift box. The easiest way to give the pond look at a gifting price point.', ARRAY['/products/lotus-boat-tealight-box/lotus-boat-tealight-box-1.jpg']::text[], ARRAY['lotus','boat','tealight','gift box','six','set','blue','pond','return gift','diwali']::text[], 'Kesar Chandan, Pineapple', '100% natural soy wax', 'Cotton, lead-free', 5, 0, 0, 320, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, '6-piece cavity gift box', true, false, 6),
('lotus-diya-candle', 'Lotus Diya Candle', 'festive-candles', 'Flat brass lotus, red centre', 'A flat cast-brass lotus with a deep red wax centre. Low, stable and unfussy — the piece people buy in quantity for pooja rooms and temple orders.', ARRAY['/products/lotus-diya-candle/lotus-diya-candle-1.jpg']::text[], ARRAY['lotus','diya','brass','red','pooja','temple','flat','bulk','diwali','traditional']::text[], 'Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 8, 2.54, 6.35, 240, 99, 125, '[{"minQty":1,"price":99},{"minQty":10,"price":90},{"minQty":25,"price":80},{"minQty":50,"price":70},{"minQty":100,"price":65}]'::jsonb, 'Sleeved, 20 per carton', true, false, 7),
('festive-lotus-urli-bowl-candle', 'Festive Lotus Urli Bowl Candle', 'festive-candles', 'Cut-brass petals, dahlia centre', 'A laser-cut brass lotus bowl holding a cream pool with a layered dahlia bloom in coral and white at the centre. The cut petals throw a pattern on the table when it is lit.', ARRAY['/products/festive-lotus-urli-bowl-candle/festive-lotus-urli-bowl-candle-1.jpg']::text[], ARRAY['lotus','urli','brass','dahlia','cut work','bowl','festive','diwali','decor','gifting']::text[], 'Rose, Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 18, 8.89, 15.24, 480, 699, 725, '[{"minQty":1,"price":699},{"minQty":10,"price":630},{"minQty":25,"price":575},{"minQty":50,"price":510},{"minQty":100,"price":455}]'::jsonb, 'Foam-nested in a printed carton', true, false, 8),
('hibiscus-urli-candle', 'Hibiscus Urli Candle', 'festive-candles', 'Three red blooms on white', 'Three hand-sculpted red hibiscus flowers with green leaves set into a wide white pool, on a scalloped gold-rim platter. Reads as fresh flowers from across a room.', ARRAY['/products/hibiscus-urli-candle/hibiscus-urli-candle-1.jpg']::text[], ARRAY['hibiscus','urli','red','flower','white','platter','gudhal','pooja','festive','decor']::text[], 'White Oud, Black Oud', '100% natural soy wax', 'Cotton, lead-free', 20, 3.81, 11.43, 520, 399, 425, '[{"minQty":1,"price":399},{"minQty":10,"price":360},{"minQty":25,"price":325},{"minQty":50,"price":290},{"minQty":100,"price":260}]'::jsonb, 'Foam-nested in a printed carton', true, false, 9),
('hibiscus-urli-sparkle-candle', 'Hibiscus Urli Sparkle Candle', 'festive-candles', 'Single bloom, gold fleck finish', 'A smaller flower-cut dish in white with one red hibiscus and a scatter of gold flecks through the wax. The compact version of our hibiscus urli, at a gifting price.', ARRAY['/products/hibiscus-urli-sparkle-candle/hibiscus-urli-sparkle-candle-1.jpg']::text[], ARRAY['hibiscus','sparkle','gold','flecks','red','small','urli','gifting','festive','flower']::text[], 'Sandalwood', '100% natural soy wax', 'Cotton, lead-free', 12, 3.81, 8.89, 280, 249, 275, '[{"minQty":1,"price":249},{"minQty":10,"price":225},{"minQty":25,"price":205},{"minQty":50,"price":180},{"minQty":100,"price":160}]'::jsonb, 'Sleeved, 16 per carton', true, false, 10),
('sunflower-urli-sparkle-candle', 'Sunflower Urli Sparkle Candle', 'festive-candles', 'One big sunflower, gold flecks', 'A full sunflower head in graded yellow with a dark seeded centre, set in a white flower-cut dish with gold flecks. The brightest thing we make, and it sells hard in summer.', ARRAY['/products/sunflower-urli-sparkle-candle/sunflower-urli-sparkle-candle-1.jpg']::text[], ARRAY['sunflower','yellow','sparkle','gold','urli','flower','bright','gifting','decor','festive']::text[], 'Sandalwood', '100% natural soy wax', 'Cotton, lead-free', 12, 3.81, 8.89, 280, 249, 275, '[{"minQty":1,"price":249},{"minQty":10,"price":225},{"minQty":25,"price":205},{"minQty":50,"price":180},{"minQty":100,"price":160}]'::jsonb, 'Sleeved, 16 per carton', true, false, 11),
('red-lotus-small-urli-candle', 'Red Lotus Small Urli Candle', 'festive-candles', 'Deep red blooms, cream pool', 'A scalloped gold-rim bowl with a cream pool and three deep red blooms with green leaves. Smaller than the big urlis and easier to place in quantity across a venue.', ARRAY['/products/red-lotus-small-urli-candle/red-lotus-small-urli-candle-1.jpg']::text[], ARRAY['red','lotus','urli','small','bowl','cream','wedding','event','festive','decor']::text[], 'Rose', '100% natural soy wax', 'Cotton, lead-free', 16, 3.81, 6.35, 380, 149, 175, '[{"minQty":1,"price":149},{"minQty":10,"price":135},{"minQty":25,"price":120},{"minQty":50,"price":110},{"minQty":100,"price":95}]'::jsonb, 'Sleeved, 12 per carton', true, false, 12),
('mogra-urli-candle', 'Mogra Urli Candle', 'festive-candles', 'A ring of jasmine buds', 'A brass flower bowl with a warm yellow pool, a pink bloom at the centre and a full ring of white mogra buds on green stems around it. Scented to match what it looks like.', ARRAY['/products/mogra-urli-candle/mogra-urli-candle-1.jpg']::text[], ARRAY['mogra','jasmine','urli','buds','yellow','brass','gajra','pooja','wedding','traditional']::text[], 'Mogra', '100% natural soy wax', 'Cotton, lead-free', 18, 2.54, 8.89, 460, 149, 175, '[{"minQty":1,"price":149},{"minQty":10,"price":135},{"minQty":25,"price":120},{"minQty":50,"price":110},{"minQty":100,"price":95}]'::jsonb, 'Foam-nested in a printed carton', true, false, 13),
('mogra-urli-bowl-candle', 'Mogra Urli Bowl Candle', 'festive-candles', 'Octagon brass, deeper pool', 'The same mogra bud ring in a heavier octagonal brass bowl with a cream pool and pink blooms. Deeper wax than the flat urli, so it runs noticeably longer.', ARRAY['/products/mogra-urli-bowl-candle/mogra-urli-bowl-candle-1.jpg']::text[], ARRAY['mogra','jasmine','octagon','brass','bowl','buds','cream','wedding','pooja','long burn']::text[], 'Mogra', '100% natural soy wax', 'Cotton, lead-free', 26, 6.35, 11.43, 640, 449, 475, '[{"minQty":1,"price":449},{"minQty":10,"price":405},{"minQty":25,"price":370},{"minQty":50,"price":330},{"minQty":100,"price":290}]'::jsonb, 'Foam-nested in a printed carton', true, false, 14),
('marigold-diya-festive-urli-candle', 'Marigold Diya Festive Urli Candle', 'festive-candles', 'Seven diyas, genda phool', 'A marble-look platter set with seven brass diyas, each holding a marigold bloom in orange or yellow, with a sunflower at the centre. This is the Diwali table in one piece.', ARRAY['/products/marigold-diya-festive-urli-candle/marigold-diya-festive-urli-candle-1.jpg']::text[], ARRAY['marigold','genda','diya','set','seven','orange','yellow','diwali','platter','festive']::text[], 'Orange, Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 8, 5.08, 15.24, 720, 599, 625, '[{"minQty":1,"price":599},{"minQty":10,"price":540},{"minQty":25,"price":490},{"minQty":50,"price":435},{"minQty":100,"price":390}]'::jsonb, 'Foam-nested in a printed carton', true, false, 15),
('elephant-urli-candle', 'Elephant Urli Candle', 'festive-candles', 'Brass elephant, lotus bowl', 'A cast brass elephant carrying a lotus-cut bowl on its back, filled with a green and coral bloom. A gifting piece that stays on the shelf long after the wax is gone.', ARRAY['/products/elephant-urli-candle/elephant-urli-candle-1.jpg']::text[], ARRAY['elephant','brass','urli','lotus','stand','hathi','gifting','housewarming','decor','wedding']::text[], 'Ginger, Mulberry, Sandalwood', '100% natural soy wax', 'Cotton, lead-free', 14, 7.62, 8.89, 520, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, 'Foam-nested in a printed carton', true, false, 16),
('turtle-urli-candle', 'Turtle Urli Candle', 'festive-candles', 'Kachua stand, plain pool', 'A detailed brass turtle carrying a scalloped bowl with a clean cream pool and no flower work. Bought for vastu as much as for looks, and the plain wax lets the brass do the talking.', ARRAY['/products/turtle-urli-candle/turtle-urli-candle-1.jpg']::text[], ARRAY['turtle','kachua','brass','urli','vastu','stand','plain','gifting','housewarming','decor']::text[], 'Ginger, Mulberry, Sandalwood', '100% natural soy wax', 'Cotton, lead-free', 14, 7.62, 8.89, 460, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, 'Foam-nested in a printed carton', true, false, 17),
('ruffle-shell-stand-candle', 'Ruffle Shell Stand Candle', 'festive-candles', 'Two wicks, sculptural brass', 'A ruffled brass shell on a slim footed stand, poured with a twin-wick cream pool. The two wicks give an even melt across the wide opening instead of a hole down the middle.', ARRAY['/products/ruffle-shell-stand-candle/ruffle-shell-stand-candle-1.jpg']::text[], ARRAY['shell','ruffle','brass','stand','twin wick','modern','sculptural','decor','gifting','table']::text[], 'Ginger, Mulberry, Sandalwood', '100% natural soy wax', 'Cotton, lead-free', 16, 7.62, 8.89, 440, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, 'Foam-nested in a printed carton', true, false, 18),
('floral-ring-urli-tealight-holder', 'Floral Ring Urli Tealight Holder', 'festive-candles', 'Ornate ring, gold-fleck pour', 'An ornate cast floral ring around a plain pour finished with gold flecks. The ring is a separate brass piece, so it can be reused with tealights afterwards.', ARRAY['/products/floral-ring-urli-tealight-holder/floral-ring-urli-tealight-holder-1.jpg']::text[], ARRAY['floral','ring','brass','tealight','holder','gold','flecks','ornate','reusable','gifting']::text[], 'Rajnigandha', '100% natural soy wax', 'Cotton, lead-free', 10, 3.81, 8.89, 300, 199, 225, '[{"minQty":1,"price":199},{"minQty":10,"price":180},{"minQty":25,"price":165},{"minQty":50,"price":145},{"minQty":100,"price":130}]'::jsonb, 'Sleeved, 12 per carton', true, false, 19),
('brass-tin-candle', 'Brass Tin Candle', 'festive-candles', 'Lidded, travels well', 'A brushed brass tin with a fitted lid and a plain soy pour. Unbreakable, stackable and the one piece on this list that survives a courier without foam.', ARRAY['/products/brass-tin-candle/brass-tin-candle-1.jpg']::text[], ARRAY['brass','tin','lid','travel','plain','minimal','corporate','hamper','unbreakable','gifting']::text[], 'White Oud', '100% natural soy wax', 'Cotton, lead-free', 20, 11.43, 8.89, 200, 699, 725, '[{"minQty":1,"price":699},{"minQty":10,"price":630},{"minQty":25,"price":575},{"minQty":50,"price":510},{"minQty":100,"price":455}]'::jsonb, 'Boxed, 24 per carton', true, false, 20),
('laxmi-charan-candle', 'Laxmi Charan Candle', 'festive-candles', 'Charan on a brass petal plate', 'Laxmi ji''s footprints in red on a cream pour, set in a fluted brass petal plate. Lit at the entrance on Dhanteras and Diwali, and one of the few designs people buy in even numbers for gifting.', ARRAY['/products/laxmi-charan-candle/laxmi-charan-candle-1.jpg']::text[], ARRAY['laxmi','charan','footprints','diwali','dhanteras','pooja','brass','red','traditional','auspicious']::text[], 'Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 10, 5.84, 7.62, 260, 149, 175, '[{"minQty":1,"price":149},{"minQty":10,"price":135},{"minQty":25,"price":120},{"minQty":50,"price":110},{"minQty":100,"price":95}]'::jsonb, 'Sleeved, 16 per carton', true, false, 21),
('baby-feet-square-urli-candle', 'Baby Feet Square Urli Candle', 'festive-candles', 'Square scalloped dish, gold flecks', 'The same charan motif in a square scalloped dish with a green leaf base and gold flecks through the wax. Squares group well, so this is the one for a row down a rangoli.', ARRAY['/products/baby-feet-square-urli-candle/baby-feet-square-urli-candle-1.jpg']::text[], ARRAY['charan','feet','square','urli','gold','flecks','rangoli','pooja','diwali','decor']::text[], 'Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 12, 6.35, 6.35, 300, 189, 215, '[{"minQty":1,"price":189},{"minQty":10,"price":170},{"minQty":25,"price":155},{"minQty":50,"price":140},{"minQty":100,"price":125}]'::jsonb, 'Sleeved, 16 per carton', true, false, 22),
('poker-glass-jar-candle', 'Poker Glass Jar Candle', 'festive-candles', 'Card suits in clear glass', 'Heart, club, spade and diamond in red and black, set into a cream pour in a clear glass tumbler. Our whole card-night line started with this one.', ARRAY['/products/poker-glass-jar-candle/poker-glass-jar-candle-1.jpg']::text[], ARRAY['poker','cards','casino','glass','jar','game night','novelty','gifting','teen patti','diwali party']::text[], 'Black Oud', '100% natural soy wax', 'Cotton, lead-free', 24, 6.35, 7.62, 220, 229, 255, '[{"minQty":1,"price":229},{"minQty":10,"price":205},{"minQty":25,"price":190},{"minQty":50,"price":165},{"minQty":100,"price":150}]'::jsonb, 'Boxed, 20 per carton', true, false, 23),
('poker-urli-candle', 'Poker Urli Candle', 'festive-candles', 'Brass leaf dish, four suits', 'A marquise-shaped brass dish with the four card suits set down a cream pour. The premium piece in the card-night line, and the one that gets gifted rather than kept.', ARRAY['/products/poker-urli-candle/poker-urli-candle-1.jpg']::text[], ARRAY['poker','cards','casino','brass','urli','marquise','teen patti','diwali party','gifting','game night']::text[], 'Black Oud', '100% natural soy wax', 'Cotton, lead-free', 16, 6.35, 11.43, 400, 449, 475, '[{"minQty":1,"price":449},{"minQty":10,"price":405},{"minQty":25,"price":370},{"minQty":50,"price":330},{"minQty":100,"price":290}]'::jsonb, 'Foam-nested in a printed carton', true, false, 24),
('poker-tealight-box', 'Poker Tealight Box', 'festive-candles', 'Four tealights, four suits', 'Four cream tealights, one per card suit, in a clear-lid box. The party-favour version of the line — cheap enough to hand out around a table.', ARRAY['/products/poker-tealight-box/poker-tealight-box-1.jpg']::text[], ARRAY['poker','cards','tealight','box','four','set','party favour','teen patti','diwali party','gifting']::text[], 'Black Oud', '100% natural soy wax', 'Cotton, lead-free', 5, 0, 0, 220, 129, 155, '[{"minQty":1,"price":129},{"minQty":10,"price":115},{"minQty":25,"price":105},{"minQty":50,"price":95},{"minQty":100,"price":85}]'::jsonb, 'Clear-lid gift box of 4', true, false, 25),
('mandala-duo-gift-box', 'Mandala Duo Gift Box', 'festive-candles', 'Printed mandala tops, boxed', 'Round candles with hand-finished mandala tops in red, blue and yellow, in a printed floral gift box. The box is the product as much as the wax — it goes straight into a hamper.', ARRAY['/products/mandala-duo-gift-box/mandala-duo-gift-box-1.jpg']::text[], ARRAY['mandala','gift box','set','printed','colourful','hamper','corporate','return gift','boho','decor']::text[], 'Lavender', '100% natural soy wax', 'Cotton, lead-free', 14, 6.35, 6.35, 400, 299, 325, '[{"minQty":1,"price":299},{"minQty":10,"price":270},{"minQty":25,"price":245},{"minQty":50,"price":220},{"minQty":100,"price":195}]'::jsonb, 'Printed gift box, sleeved', true, false, 26),
('rasmalai-cup-candle', 'Rasmalai Cup Candle', 'festive-candles', 'Saffron and pista, in glass', 'Rasmalai in a small glass cup, right down to the saffron strands and the pistachio scatter on top. Sold loose or as a tray of nine for dessert-counter displays.', ARRAY['/products/rasmalai-cup-candle/rasmalai-cup-candle-1.jpg']::text[], ARRAY['rasmalai','dessert','mithai','sweet','glass','cup','novelty','return gift','kesar','food']::text[], 'Kesar Chandan', '100% natural soy wax', 'Cotton, lead-free', 8, 6.35, 6.35, 110, 129, 155, '[{"minQty":1,"price":129},{"minQty":10,"price":115},{"minQty":25,"price":105},{"minQty":50,"price":95},{"minQty":100,"price":85}]'::jsonb, 'Tray of 9, 36 per carton', true, false, 27)
insert into public.site_settings (id, data) values (1, '{"businessName":"Sugandha Candles","tagline":"100% natural soy wax. Smokeless burn. Imported fragrance.","aboutBlurb":"Every candle here is poured by hand in 100% natural soy wax — never paraffin. Soy burns cool, clean and smokeless, so it throws scent instead of soot, and it lasts far longer for the same size. The fragrance oils are imported, skin-safe and IFRA-grade. Buy one piece or a thousand.","instagramHandle":"sugandha_candles_","email":"sugandha.workspace@gmail.com","addressLines":["Sugandha Candles","Gaur City, Greater Noida","Uttar Pradesh 201009, India"],"currency":"INR","fragrances":["Rose","British Rose","Sandalwood","Kesar Chandan","White Oud","Black Oud","Mogra","Jasmine","Ginger","Mulberry","Phool Chameli","Bela","Rajnigandha","Lavender","Lemongrass","Citronella","Eucalyptus","Camphor","Wood","Orange","Mango","Pineapple","Strawberry","Blueberry","Green Apple","Fruit Basket","French Vanilla","Cotton Candy","Sweet Candy","Blue Ocean","One Million","Oscar","Poems"],"termsIntro":"Everything about ordering, in plain words. If something here does not suit your order, just ask — most of it has room in it.","termsSections":[{"heading":"Payment","body":["65% advance to confirm the order. The remaining 35% before dispatch.","Payment by UPI, IMPS, NEFT or RTGS. Details are shared once you confirm.","For repeat buyers with three or more completed orders, we can move to 50% advance.","We do not accept cash on delivery or post-dated cheques."]},{"heading":"Order size","body":["There is no minimum order. A single piece is welcome, and so is a bulk order.","Rates step down at 10, 25, 50 and 100 pieces. The step applies on its own — you do not have to ask.","Slabs are counted per design, so buying more of one design is what brings the rate down.","You may mix designs and fragrances freely within one order."]},{"heading":"Fragrance","body":["Every candle ships in our house fragrance for that design unless you choose otherwise.","Orders of 50 pieces and above can pick any fragrance from our list, free of charge.","All oils are imported, IFRA-grade and skin-safe. We do not use industrial-grade perfume.","Tell us if the candles are for a temple, a hospital or a closed room and we will suggest a lighter throw."]},{"heading":"Wax and burn","body":["100% natural soy wax. No paraffin, no blends, no hardener.","Soy burns cool and smokeless, so it does not blacken walls, jars or brass.","For the cleanest burn, trim the wick to about 5 mm before every light.","First burn should run until the top layer melts fully to the edge. That is what stops tunnelling."]},{"heading":"Lead time","body":["Ready designs: 5 to 7 working days from advance payment.","Custom fragrance, colour or vessel: 12 to 18 working days.","Festive season (September to November) adds roughly a week. Plan backwards from your date."]},{"heading":"Customisation","body":["Private label with your own printed label and box is available from 500 pieces per design.","Custom colour matching needs a reference shade and 500 pieces minimum.","Corporate and wedding orders can have a printed insert card added at cost."]},{"heading":"Samples","body":["Samples are charged at the single-piece rate plus actual courier.","Sample cost is adjusted against your first bulk order of the same design.","Samples ship in 3 to 4 working days."]},{"heading":"Packing and shipping","body":["Every piece is bubble-wrapped and packed in corrugated cartons with corner protection.","Brass and glass pieces are foam-nested on top of that.","Freight is at your account, or we arrange it and bill at actuals.","Transit insurance is available on request and worth it on brass urli orders."]},{"heading":"Breakage and returns","body":["Report transit breakage within 48 hours of delivery with photographs of the outer carton and the damaged pieces.","Verified breakage is replaced free in your next dispatch.","We do not accept returns for change of mind, or on custom and private-label production."]},{"heading":"Colour and finish","body":["These are hand-poured, hand-finished products. Slight variation in colour and surface between batches is normal and is not a defect.","Natural soy may develop a light frosted pattern on the surface over time. It does not affect burn or scent."]}]}'::jsonb)
